{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 明示参与组织，并在条件分支中作为汇报接收方；角色名本身不提供其他权限。",
      "sources": [
        {"quote": "请 PM 组织检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "machine",
      "verdict": "SUPPORT",
      "reason": "轨道机是被检查状态所属的系统，也是禁止重启的对象。",
      "sources": [
        {"quote": "轨道机当前运行状态", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "不得重启轨道机", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "runtime_status",
      "verdict": "SUPPORT",
      "reason": "当前运行状态是检查对象；文本未要求修改该状态。",
      "sources": [
        {"quote": "检查轨道机当前运行状态", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "alarm_logs",
      "verdict": "SUPPORT",
      "reason": "最近一小时的告警日志是现有检查输入，不是要求生成或修改的输出。",
      "sources": [
        {"quote": "检查轨道机当前运行状态及最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "log_window",
      "verdict": "SUPPORT",
      "reason": "最近一小时限定告警日志的时间范围。",
      "sources": [
        {"quote": "最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "请求明确要求 PM 组织检查，支持主层的组织事件及 REQUIRED 模态。",
      "sources": [
        {"quote": "请 PM 组织检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "check",
      "verdict": "SUPPORT",
      "reason": "检查是组织事件的补足内容；局部未单独标明检查执行者或独立模态。UNSTATED 不表示检查可省略。",
      "sources": [
        {"quote": "组织检查轨道机当前运行状态及最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "generate",
      "verdict": "SUPPORT",
      "reason": "形成文件是请求中并列要求的产出事件。",
      "sources": [
        {"quote": "请 PM 组织检查轨道机当前运行状态及最近一小时告警日志，并形成 orbit-review.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "review_file",
      "verdict": "SUPPORT",
      "reason": "文件由形成事件产出，支持 GENERATED_OUTPUT；没有现有文件输入的表述。",
      "sources": [
        {"quote": "形成 orbit-review.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "shutdown_detected",
      "verdict": "SUPPORT",
      "reason": "发现停机是条件前件中的已发现状态，不是独立要求执行的发现事件。",
      "sources": [
        {"quote": "若发现停机", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "stop",
      "verdict": "SUPPORT",
      "reason": "发现停机时要求立即停止后续检查；事件语义正确限定了停止对象。",
      "sources": [
        {"quote": "若发现停机，任务应立即停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "subsequent_checks",
      "verdict": "SUPPORT",
      "reason": "后续检查是停止事件的补足对象，不是另行要求执行的事件。",
      "sources": [
        {"quote": "停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "immediately",
      "verdict": "SUPPORT",
      "reason": "立即明确修饰停止事件；该节点没有将其扩大为整个任务的时限。",
      "sources": [
        {"quote": "立即停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "report",
      "verdict": "SUPPORT",
      "reason": "汇报与停止并列，处于发现停机的条件后件，受到应的要求约束。",
      "sources": [
        {"quote": "若发现停机，任务应立即停止后续检查并向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "restart",
      "verdict": "SUPPORT",
      "reason": "不得明确禁止重启。用肯定极性的重启事件承载 FORBIDDEN 模态有源文支持；末尾禁令未明示仅在条件成立时适用。",
      "sources": [
        {"quote": "不得重启轨道机", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM 是组织事件的明示参与者，依据是实际谓词绑定，不是角色称谓。",
      "sources": [
        {"quote": "PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r2",
      "verdict": "SUPPORT",
      "reason": "组织检查支持将检查作为组织内容的组成事件；该关系不确定实际检查执行者。",
      "sources": [
        {"quote": "组织检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "运行状态直接绑定为检查对象，不是依据、方法或输出。",
      "sources": [
        {"quote": "检查轨道机当前运行状态", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "及将告警日志与运行状态并列为同一检查谓词的对象。",
      "sources": [
        {"quote": "检查轨道机当前运行状态及最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "及明确连接两个检查对象。",
      "sources": [
        {"quote": "当前运行状态及最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "轨道机当前运行状态支持状态数据归属于轨道机的属性组成解释。",
      "sources": [
        {"quote": "轨道机当前运行状态", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "一小时时间窗是告警日志的限定属性。",
      "sources": [
        {"quote": "最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r8",
      "verdict": "SUPPORT",
      "reason": "并连接组织检查与形成文件两个请求谓词。",
      "sources": [
        {"quote": "组织检查轨道机当前运行状态及最近一小时告警日志，并形成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "并列形成谓词沿用前面的 PM 主语，支持 PM 参与形成文件；不因此推断 PM 亲自执行检查。",
      "sources": [
        {"quote": "请 PM 组织检查轨道机当前运行状态及最近一小时告警日志，并形成 orbit-review.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r10",
      "verdict": "SUPPORT",
      "reason": "文件是形成事件的直接产出。",
      "sources": [
        {"quote": "形成 orbit-review.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r11",
      "verdict": "SUPPORT",
      "reason": "若发现停机明确条件化停止后续检查，并非完成条件。",
      "sources": [
        {"quote": "若发现停机，任务应立即停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r12",
      "verdict": "SUPPORT",
      "reason": "同一若条件覆盖应所辖的并列汇报事件。",
      "sources": [
        {"quote": "若发现停机，任务应立即停止后续检查并向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r13",
      "verdict": "CONTRADICT",
      "reason": "任务在这里是主语，停止的明示对象是后续检查。STOP_OF 指向 TASK 将主语误作停止对象，并扩大为整个任务停止，与 r14 的较窄对象产生范围冲突。",
      "sources": [
        {"quote": "任务应立即停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r14",
      "verdict": "SUPPORT",
      "reason": "停止直接作用于后续检查；文本没有要求整个任务停止。",
      "sources": [
        {"quote": "停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r15",
      "verdict": "SUPPORT",
      "reason": "立即是停止谓词的时间属性。",
      "sources": [
        {"quote": "立即停止", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r16",
      "verdict": "SUPPORT",
      "reason": "并明确连接停止和汇报；没有明示必须完成停止后才开始汇报的顺序。",
      "sources": [
        {"quote": "停止后续检查并向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r17",
      "verdict": "SUPPORT",
      "reason": "向 PM 将 PM 标为汇报接收者，不是汇报执行者。",
      "sources": [
        {"quote": "向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r18",
      "verdict": "SUPPORT",
      "reason": "轨道机是重启操作的直接作用对象。",
      "sources": [
        {"quote": "重启轨道机", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r19",
      "verdict": "SUPPORT",
      "reason": "任务文本明确包含重启禁令；TASK 在该关系中表示任务级约束所属范围，不表示某角色具有禁令审批权。",
      "sources": [
        {"quote": "不得重启轨道机", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "check_scope",
      "verdict": "SUPPORT",
      "reason": "及要求检查两个列出的对象，支持 ALL，而非任选其一。",
      "sources": [
        {"quote": "检查轨道机当前运行状态及最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "shutdown_guard",
      "verdict": "SUPPORT",
      "reason": "条件表达式引用发现停机的状态，没有将前件提升为独立执行义务。",
      "sources": [
        {"quote": "若发现停机", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "log_window_quantity",
      "verdict": "SUPPORT",
      "reason": "数值一小时、日志目标及 preceding log coverage duration 指标均有支持。它限定被检查日志的时间跨度，不是检查执行时限、输出数量或验收阈值；有限 use 枚举没有时间窗类别，UNKNOWN 在此不能被解释为源文时间窗语义未知。",
      "sources": [
        {"quote": "最近一小时告警日志", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    }
  ],
  "findings": [
    {
      "id": "f_wrong_stop_binding",
      "kind": "WRONG_BINDING",
      "candidate_ids": ["r13", "r14", "stop"],
      "sources": [
        {"quote": "任务应立即停止后续检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ],
      "reason": "r13 将主语任务绑定为停止对象。明示停止对象是后续检查，已经由 stop 和 r14 正确体现；任务主语不能通过 STOP_OF 表达。此检查保留原候选并报告冲突。"
    },
    {
      "id": "f_stop_scope_conflict",
      "kind": "SCOPE_CONFLICT",
      "candidate_ids": ["r13", "r14"],
      "sources": [
        {"quote": "若发现停机，任务应立即停止后续检查并向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ],
      "reason": "r13 表示任务整体停止，r14 表示后续检查停止。源文支持后者，且同一条件下仍要求汇报；不能把任务整体停止与停止后续检查视为等价范围。"
    },
    {
      "id": "f_missing_task_subject",
      "kind": "MISSED_SEMANTICS",
      "candidate_ids": ["stop", "report", "r13", "r17"],
      "sources": [
        {"quote": "任务应立即停止后续检查并向 PM 汇报", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ],
      "reason": "源文以任务为停止及汇报的共享主语，图没有正确表示这项主语绑定。实际人员执行者仍未说明；PM 只在该分支中明示为接收者。可表示任务这一抽象参与主体，不得据此补出 PM 或其他人员执行者。"
    }
  ],
